'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var hasProp = require( '@stdlib/assert/has-property' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var Title = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Title, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `fontWeight` property', function test( t ) {
	var v = new Title();
	t.strictEqual( hasOwnProp( v, 'fontWeight' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'fontWeight' ), true, 'returns expected value' );
	t.strictEqual( isUndefined( v.fontWeight ), true, 'returns expected value' );

	v = new Title({
		'fontWeight': 'bold'
	});
	t.strictEqual( isString( v.fontWeight ), true, 'returns expected value' );

	v = new Title({
		'fontWeight': 600
	});
	t.strictEqual( isString( v.fontWeight ), true, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `fontWeight` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		'foo',
		6,
		NaN,
		null,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var title = new Title();
			title.fontWeight = value;
		};
	}
});

tape( 'the constructor returns an instance having a `fontWeight` property', function test( t ) {
	var title = new Title();
	t.strictEqual( isUndefined( title.fontWeight ), true, 'returns expected value' );

	title = new Title({
		'fontWeight': 'bold'
	});
	t.strictEqual( title.fontWeight, 'bold', 'returns expected value' );

	title = new Title({
		'fontWeight': 'lighter'
	});
	t.strictEqual( title.fontWeight, 'lighter', 'returns expected value' );

	title = new Title({
		'fontWeight': '600'
	});
	t.strictEqual( title.fontWeight, '600', 'returns expected value' );

	title = new Title({
		'fontWeight': 800
	});
	t.strictEqual( title.fontWeight, '800', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `fontWeight` property which can be set to a valid value', function test( t ) {
	var title = new Title();

	title.fontWeight = 'bold';
	t.strictEqual( title.fontWeight, 'bold', 'returns expected value' );

	title.fontWeight = 'lighter';
	t.strictEqual( title.fontWeight, 'lighter', 'returns expected value' );

	title.fontWeight = '600';
	t.strictEqual( title.fontWeight, '600', 'returns expected value' );

	title.fontWeight = 800;
	t.strictEqual( title.fontWeight, '800', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `fontWeight` property is set to a new value', function test( t ) {
	var title;
	var count;

	title = new Title();
	count = 0;

	title.on( 'change', onChange );

	title.fontWeight = 'lighter';
	t.strictEqual( count, 1, 'returns expected value' );

	title.fontWeight = 'bold';
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	title.fontWeight = 'bold';
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
